import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for Axis.drawLabel.
 * Note: Since drawLabel is protected, we use a concrete subclass for testing.
 */
public class Axis_drawLabel_TriageGen1Test {

    private TestAxis axis;
    private Graphics2D g2;
    private Rectangle2D plotArea;
    private Rectangle2D dataArea;
    private AxisState state;
    private PlotRenderingInfo plotState;
    private ChartRenderingInfo chartRenderingInfo;
    private EntityCollection entityCollection;

    // Concrete implementation of the abstract Axis class for testing protected methods
    private static class TestAxis extends Axis {
        protected TestAxis(String label) {
            super(label);
        }

        @Override
        public void configure() {}

        @Override
        public AxisSpace reserveSpace(Graphics2D g2, org.jfree.chart.plot.Plot plot, Rectangle2D plotArea, RectangleEdge edge, AxisSpace space) {
            return null;
        }

        @Override
        public AxisState draw(Graphics2D g2, double cursor, Rectangle2D plotArea, Rectangle2D dataArea, RectangleEdge edge, PlotRenderingInfo plotState) {
            return null;
        }

        @Override
        public List<Number> refreshTicks(Graphics2D g2, AxisState state, Rectangle2D dataArea, RectangleEdge edge) {
            return null;
        }
    }

    @Before
    public void setUp() throws Exception {
        axis = new TestAxis("Test Axis");
        g2 = mock(Graphics2D.class);
        plotArea = new Rectangle2D.Double(0, 0, 500, 500);
        dataArea = new Rectangle2D.Double(50, 50, 400, 400);
        state = mock(AxisState.class);

        // Setup default font and paint to avoid NullPointerException in method
        axis.setLabelFont(new Font("SansSerif", Font.PLAIN, 12));
        axis.setLabelPaint(Color.BLACK);
        axis.setLabelInsets(new RectangleInsets(2, 2, 2, 2));

        FontMetrics fm = mock(FontMetrics.class);
        when(g2.getFontMetrics()).thenReturn(fm);
        // Mock bounds for text to ensure math doesn't fail
        when(fm.getHeight()).thenReturn(15);
        when(fm.getAscent()).thenReturn(10);
        when(fm.getDescent()).thenReturn(5);

        // Setup plotState hierarchy
        plotState = mock(PlotRenderingInfo.class);
        chartRenderingInfo = mock(ChartRenderingInfo.class);
        entityCollection = new EntityCollection();
        when(plotState.getOwner()).thenReturn(chartRenderingInfo);
        when(chartRenderingInfo.getEntityCollection()).thenReturn(entityCollection);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDrawLabel_NullState() {
        axis.drawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, null, plotState);
    }

    @Test
    public void testDrawLabel_NullOrEmptyLabel() {
        // Test null label
        AxisState resultNull = axis.drawLabel(null, g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        assertEquals(state, resultNull);

        // Test empty label
        AxisState resultEmpty = axis.drawLabel("", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        assertEquals(state, resultEmpty);
    }

    @Test
    public void testDrawLabel_TopEdge() {
        when(state.getCursor()).thenReturn(100.0);

        AxisState result = axis.drawLabel("TopLabel", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);

        assertEquals(state, result);
        verify(state).cursorUp(any(Double.class));
        // Check if entity was added to collection (hotspot logic)
        assertNotNull(entityCollection.get(0));
    }

    @Test
    public void testDrawLabel_BottomEdge() {
        when(state.getCursor()).thenReturn(100.0);

        AxisState result = axis.drawLabel("BottomLabel", g2, plotArea, dataArea, RectangleEdge.BOTTOM, state, plotState);

        assertEquals(state, result);
        verify(state).cursorDown(any(Double.class));
        assertNotNull(entityCollection.get(0));
    }

    @Test
    public void testDrawLabel_LeftEdge() {
        when(state.getCursor()).thenReturn(100.0);

        AxisState result = axis.drawLabel("LeftLabel", g2, plotArea, dataArea, RectangleEdge.LEFT, state, plotState);

        assertEquals(state, result);
        verify(state).cursorLeft(any(Double.class));
        assertNotNull(entityCollection.get(0));
    }

    @Test
    public void testDrawLabel_RightEdge() {
        when(state.getCursor()).thenReturn(100.0);

        AxisState result = axis.drawLabel("RightLabel", g2, plotArea, dataArea, RectangleEdge.RIGHT, state, plotState);

        assertEquals(state, result);
        verify(state).cursorRight(any(Double.class));
        assertNotNull(entityCollection.get(0));
    }

    @Test
    public void testDrawLabel_NoPlotState() {
        // Test branch where plotState is null
        when(state.getCursor()).thenReturn(100.0);
        AxisState result = axis.drawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, null);
        assertEquals(state, result);
    }

    @Test
    public void testDrawLabel_NoEntityCollection() {
        // Test branch where entities is null
        when(state.getCursor()).thenReturn(100.0);
        when(plotState.getOwner()).thenReturn(chartRenderingInfo);
        when(chartRenderingInfo.getEntityCollection()).thenReturn(null);

        axis.drawLabel("Label", g2, plotArea, dataArea, RectangleEdge.TOP, state, plotState);
        // No exception should be thrown
    }
}
